  "admin.categories.page.showingCount": { en: "Showing {count} of {total} categories", ar: "عرض {count} من أصل {total} فئات", ur: "{count} از {total} زمرے دکھائے جا رہے ہیں" , es: "Mostrando {count} de categorías {total}", fr: "Affichage des catégories {count} de {total}", de: "Anzeigen {count} von {total} Kategorien", hi: "{total} श्रेणियों का {count} दिखा रहा है", zh: "显示 {total} 类别的 {count}", pt: "Mostrando categorias {count} de {total}"},
  "admin.categories.page.showingRange": { en: "Showing {from}-{to} of {total} categories", ar: "عرض {from}-{to} من أصل {total} فئات", ur: "{from}-{to} از {total} زمرے دکھائے جا رہے ہیں" , es: "Mostrando {from}-{to} de categorías {total}", fr: "Affichage des catégories {from}-{to} des catégories {total}", de: "Anzeigen {from}-{to} von {total} Kategorien", hi: "{total} श्रेणियों के {from}-{to} दिखा रहा है", zh: "显示 {total} 类别的 {from}-{to}", pt: "Mostrando categorias {from}-{to} de {total}"},
  "admin.categories.page.subtitle": { en: "Manage category hierarchy and dynamic attributes", ar: "إدارة تسلسل الفئات والسمات الديناميكية", ur: "زمرہ درجہ بندی اور متحرک خصوصیات کا انتظام کریں" , es: "Gestionar la jerarquía de categoría y los atributos dinámicos", fr: "Gérer la hiérarchie de catégorie et les attributs dynamiques", de: "Verwalten von Kategoriehierarchie und dynamischen Attributen", hi: "प्रबंधन श्रेणी पदानुक्रम और गतिशील विशेषताओं", zh: "管理类别等级和动态属性", pt: "Gerenciar hierarquia de categorias e atributos dinâmicos", tr: "kategori hiyerarşisi ve dinamik özellikleri yönetin"},
  "admin.categories.page.title": { en: "Category Management", ar: "إدارة الفئات", ur: "زمرہ مینجمنٹ" , es: "Categoría Gestión", fr: "Gestion de catégorie", de: "Kategoriemanagement", hi: "श्रेणी प्रबंधन", zh: "类别 管理", pt: "Gestão de Categorias", tr: "Kategori Yönetimi"},
