  "admin.categories.parent.badgeSubcategory": { en: "Subcategory", ar: "فئة فرعية", ur: "ذیلی زمرہ" , es: "Subcategoría", fr: "Sous-catégorie", de: "Unterkategorie", hi: "उपश्रेणी", zh: "子类", pt: "Sub- categoria"},
