  "admin.categories.parent.none": { en: "None", ar: "لا شيء", ur: "کوئی نہیں" , es: "Ninguno", fr: "Aucune", de: "Keine", hi: "कोई नहीं", zh: "无", pt: "Nenhum", tr: "Hiçbir şey yok"},
  "admin.categories.parent.selfHint": { en: "A category cannot be selected as its own parent.", ar: "لا يمكن اختيار فئة كصورة أصلها لنفسها.", ur: "کسی زمرے کو اپنے والدین کے طور پر منتخب نہیں کیا جا سکتا۔" , es: "Una categoría no puede ser seleccionada como su propio padre.", fr: "Une catégorie ne peut être choisie comme son propre parent.", de: "Eine Kategorie kann nicht als eigenes Mutterunternehmen ausgewählt werden.", hi: "एक श्रेणी को अपने माता-पिता के रूप में चुना नहीं जा सकता है।", zh: "无法选择一个类别为自己的父类 。", pt: "Uma categoria não pode ser selecionada como seu próprio pai.", tr: "Bir kategori kendi ebeveyni olarak seçilebilir."},
  "admin.categories.parent.selfMessage": { en: "A category cannot be its own parent.", ar: "لا يمكن أن تكون الفئة أصلاً لنفسها.", ur: "کوئی زمرہ اپنا والدین نہیں ہو سکتا۔" , es: "Una categoría no puede ser su propio padre.", fr: "Une catégorie ne peut être son propre parent.", de: "Eine Kategorie kann nicht ihr eigenes Elternteil sein.", hi: "एक श्रेणी अपने माता-पिता नहीं हो सकती है।", zh: "一个类别不能是自己的父母。", pt: "Uma categoria não pode ser o seu próprio pai.", tr: "Bir kategori kendi ebeveyni olamaz."},
