  "admin.products.errors.contactAdmin": { en: "Contact an administrator to grant you access.", ar: "يرجى التواصل مع المسؤول لمنحك الصلاحية.", ur: "رسائی کے لیے ایڈمنسٹریٹر سے رابطہ کریں۔", es: "Contacte con un administrador para otorgarle acceso.", fr: "Contactez un administrateur pour vous accorder l'accès.", de: "Kontaktieren Sie einen Administrator, um Ihnen Zugriff zu gewähren.", hi: "आपको एक्सेस प्रदान करने के लिए एक व्यवस्थापक से संपर्क करें।", zh: "联系管理员来允许您访问 。", pt: "Contacte um administrador para lhe conceder acesso.", tr: "Size erişmek için bir yöneticiyle iletişime geçin." },
  "admin.products.errors.noPermission": { en: "You don't have permission to modify this {resource}.", ar: "لا تملك صلاحية تعديل {resource} هذا.", ur: "آپ کو اس {resource} میں ترمیم کرنے کی اجازت نہیں۔", fr: "Vous n'avez pas la permission de modifier ce {resource}.", de: "Sie haben keine Berechtigung, dieses {resource} zu ändern.", hi: "आपको इस {resource} को संशोधित करने की अनुमति नहीं है।", zh: "你没有修改{resource}的许可.", pt: "Você não tem permissão para modificar este {resource}.", tr: "Bu {resource}'yi değiştirme izniniz yok.", es: "No tienes permiso para modificar esto {resource}." },
