  "admin.employees.modal.deleteOneTitle": { en: "Delete \"{name}\"?", ur: "کیا \"{name}\" کو حذف کرنا ہے؟", ar: "هل تريد حذف \"{name}\"؟", es: "¿Descubrir “{name}”?", fr: "Détecter « {name} » ?", de: "Entfernen Sie „{name}“?", hi: "\"{name}\" को हटा दें?", zh: "删除“{name}”吗?", pt: "Eliminar “{name}”?", tr: "“{name}” için tıklayınız." },
  "admin.employees.modal.deleteOneBody": { en: "This action cannot be undone. All employee data will be permanently removed.", ur: "یہ عمل واپس نہیں ہو سکتا۔ ملازم کا تمام ڈیٹا مستقل طور پر حذف ہو جائے گا۔", ar: "لا يمكن التراجع عن هذا الإجراء. ستتم إزالة جميع بيانات الموظف نهائيًا.", es: "Esta acción no puede ser anulada.Todos los datos de los empleados serán eliminados permanentemente.", fr: "Cette action ne peut pas être annulée.Tous les données des employés seront supprimées en permanence.", de: "Diese Aktion kann nicht abgesagt werden.Alle Mitarbeiterdaten werden dauerhaft gelöscht.", hi: "यह कार्रवाई अस्वीकार नहीं की जा सकती. सभी कर्मचारियों के डेटा को स्थायी रूप से हटा दिया जाएगा.", zh: "此操作不能被取消,所有员工数据将永久删除。", pt: "Esta ação não pode ser anulada.Todos os dados dos funcionários serão removidos permanentemente.", tr: "Bu eylem reddedilemez. tüm çalışan verileri kalıcı olarak silinecektir." },
  "admin.employees.modal.deleteManyTitle": { en: "Delete {count} employees?", ur: "کیا {count} ملازمین حذف کرنے ہیں؟", ar: "هل تريد حذف {count} موظفين؟", es: "¿Eliminar a los empleados de {count}?", fr: "Vous supprimez les employés de {count} ?", de: "Entfernen Sie {count} Mitarbeiter?", hi: "{count} कर्मचारियों को हटा दें?", zh: "{count}的员工被删除?", pt: "Eliminar os funcionários do {count}?", tr: "{count} çalışanları silinir mi?" },
  "admin.employees.modal.deleteManyBody": { en: "This action cannot be undone. All selected employees will be permanently removed.", ur: "یہ عمل واپس نہیں ہو سکتا۔ تمام منتخب ملازمین مستقل طور پر حذف ہو جائیں گے۔", ar: "لا يمكن التراجع عن هذا الإجراء. ستتم إزالة جميع الموظفين المحددين نهائيًا.", es: "Esta acción no puede ser anulada.Todos los empleados seleccionados serán retirados permanentemente.", fr: "Cette action ne peut être annulée.Tous les employés sélectionnés seront retirés en permanence.", de: "Diese Aktion kann nicht abgesagt werden.Alle ausgewählten Mitarbeiter werden dauerhaft entfernt.", hi: "यह कार्रवाई अस्वीकार नहीं की जा सकती. सभी चुने हुए कर्मचारियों को स्थायी रूप से हटा दिया जाएगा.", zh: "这项行动不能被拒绝,所有选定的员工将被永久撤销。", pt: "Esta ação não pode ser anulada.Todos os funcionários selecionados serão removidos permanentemente.", tr: "Bu eylem reddedilemez. tüm seçilmiş çalışanlar kalıcı olarak kaldırılacaktır." },
  "admin.employees.modal.confirmDeleteMany": { en: "Delete {count}", ur: "{count} حذف کریں", ar: "حذف {count}", es: "Eliminar {count}", fr: "Supprimer {count}", de: "Entfernen {count}", hi: "{count} को हटा दें", zh: "删除 {count}", pt: "Remover {count}", tr: "{count} İndir" },
